# Writes THIRD-PARTY-NOTICES.txt (repository root) from the IDE's notices resource
# (ide/src/FreexComp.Ide.Core/Resources/ThirdPartyNotices.json: names, versions, licenses, texts) and the
# "Source" column of THIRD-PARTY-NOTICES.md, section "Shipped with the product".
#
#   -Check          write nothing; exit code 1 and the line "THIRD-PARTY-NOTICES.txt is out of date" when
#                   the generated bytes differ from the file (or the file is missing), else exit code 0
#   -Root <dir>     repository root (default: the parent of this script's directory)
#   -Output <file>  file to write or to check (default: <Root>/THIRD-PARTY-NOTICES.txt)
#
# Exit codes: 0 = written / up to date, 1 = out of date (-Check), 2 = input error (message on stderr,
# nothing written). Reads local files only. The output is deterministic: no date, no machine or user
# name, no absolute path. Works in Windows PowerShell 5.1; keep this file ASCII.
param(
    [switch]$Check,
    [string]$Root,
    [string]$Output
)

$ErrorActionPreference = 'Stop'

function Get-NormalizedText([string]$text) {
    # LF line endings, no trailing blanks, no leading or trailing empty lines.
    $lines = New-Object 'System.Collections.Generic.List[string]'
    foreach ($line in $text.Replace("`r`n", "`n").Replace("`r", "`n").Split("`n")) {
        $lines.Add($line.TrimEnd(' ', "`t"))
    }
    while ($lines.Count -gt 0 -and $lines[0].Length -eq 0) { $lines.RemoveAt(0) }
    while ($lines.Count -gt 0 -and $lines[$lines.Count - 1].Length -eq 0) { $lines.RemoveAt($lines.Count - 1) }
    return [string]::Join("`n", $lines.ToArray())
}

function Get-TableCells([string]$line) {
    $inner = $line.Trim()
    if ($inner.StartsWith('|')) { $inner = $inner.Substring(1) }
    if ($inner.EndsWith('|')) { $inner = $inner.Substring(0, $inner.Length - 1) }
    $cells = New-Object 'System.Collections.Generic.List[string]'
    foreach ($cell in $inner.Split('|')) { $cells.Add($cell.Trim()) }
    return , $cells.ToArray()
}

try {
    if (-not $Root) { $Root = Split-Path -Parent $PSScriptRoot }
    $Root = [System.IO.Path]::GetFullPath($Root)
    if (-not $Output) { $Output = Join-Path $Root 'THIRD-PARTY-NOTICES.txt' }
    $Output = [System.IO.Path]::GetFullPath($Output)
    $utf8 = New-Object System.Text.UTF8Encoding($false)

    $jsonName = 'ide/src/FreexComp.Ide.Core/Resources/ThirdPartyNotices.json'
    $tableName = 'THIRD-PARTY-NOTICES.md'
    foreach ($name in @($jsonName, $tableName)) {
        if (-not (Test-Path -LiteralPath (Join-Path $Root $name) -PathType Leaf)) { throw "input file not found: $name" }
    }

    # --- entries ---------------------------------------------------------------------------------
    $parsed = ConvertFrom-Json ([System.IO.File]::ReadAllText((Join-Path $Root $jsonName), $utf8))
    $entries = @($parsed)
    if ($entries.Count -eq 0) { throw 'ThirdPartyNotices.json has no entries' }
    $byName = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::Ordinal)
    foreach ($entry in $entries) {
        foreach ($field in @('name', 'version', 'license')) {
            if ([string]::IsNullOrWhiteSpace([string]$entry.$field)) { throw "an entry has no '$field'" }
        }
        if ($byName.ContainsKey([string]$entry.name)) { throw "entry '$($entry.name)' appears twice" }
        $byName.Add([string]$entry.name, $entry)
    }

    $texts = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::Ordinal)
    foreach ($entry in $entries) {
        $text = $entry.text
        if ($null -eq $text) {
            # "textOf" names the entry that stores the shared text.
            $other = $null
            if ($null -ne $entry.textOf -and $byName.ContainsKey([string]$entry.textOf)) { $other = $byName[[string]$entry.textOf] }
            if ($null -eq $other -or $null -eq $other.text) {
                throw "entry '$($entry.name)' has no text (textOf '$($entry.textOf)')"
            }
            $text = $other.text
        }
        $text = Get-NormalizedText ([string]$text)
        if ($text.Length -eq 0) { throw "entry '$($entry.name)' has an empty text" }
        $texts.Add([string]$entry.name, $text)
    }

    # --- "Source" column of the table ------------------------------------------------------------
    $tableLines = [System.IO.File]::ReadAllText((Join-Path $Root $tableName), $utf8).Replace("`r`n", "`n").Split("`n")
    $start = -1
    for ($i = 0; $i -lt $tableLines.Length; $i++) {
        if ($tableLines[$i].Trim() -ceq '## Shipped with the product') { $start = $i; break }
    }
    if ($start -lt 0) { throw "$tableName has no section 'Shipped with the product'" }
    $header = $null
    $rows = New-Object 'System.Collections.Generic.List[object]'
    for ($i = $start + 1; $i -lt $tableLines.Length; $i++) {
        $line = $tableLines[$i].Trim()
        if ($line.StartsWith('#')) { break }
        if (-not $line.StartsWith('|')) { continue }
        $cells = Get-TableCells $line
        if ($null -eq $header) { $header = $cells; continue }
        if (($cells -join '') -match '^[-: ]*$') { continue }
        $rows.Add($cells)
    }
    if ($null -eq $header) { throw "section 'Shipped with the product' of $tableName has no table" }
    $componentColumn = [Array]::IndexOf($header, 'Component')
    $sourceColumn = [Array]::IndexOf($header, 'Source')
    if ($componentColumn -lt 0 -or $sourceColumn -lt 0) { throw "the table needs the columns 'Component' and 'Source'" }

    # A row belongs to the entry whose name its Component cell equals, or starts with followed by " (" or
    # ","; the longest such name wins.
    $sources = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::Ordinal)
    foreach ($cells in $rows) {
        if ($cells.Length -le $componentColumn -or $cells.Length -le $sourceColumn) {
            throw "table row with too few cells: $($cells -join ' | ')"
        }
        $component = $cells[$componentColumn]
        $best = $null
        foreach ($name in $byName.Keys) {
            $fits = ($component -ceq $name) -or
                $component.StartsWith($name + ' (', [System.StringComparison]::Ordinal) -or
                $component.StartsWith($name + ',', [System.StringComparison]::Ordinal)
            if ($fits -and ($null -eq $best -or $name.Length -gt $best.Length)) { $best = $name }
        }
        if ($null -eq $best) { continue }
        if ($sources.ContainsKey($best)) { throw "entry '$best' has more than one table row" }
        if ($cells[$sourceColumn].Length -eq 0) { throw "the table row of '$best' has no source" }
        $sources.Add($best, $cells[$sourceColumn])
    }

    # --- output ----------------------------------------------------------------------------------
    $names = New-Object string[] $byName.Count
    $byName.Keys.CopyTo($names, 0)
    [Array]::Sort($names, [System.StringComparer]::Ordinal)
    $rule = New-Object string ('=', 80)
    $out = New-Object System.Text.StringBuilder
    [void]$out.Append("FreexComp third-party notices`n`n")
    [void]$out.Append("This file is generated by scripts/gen-notices.ps1. Do not edit it.`n")
    [void]$out.Append("Each component below is used unmodified under the license shown.`n")
    foreach ($name in $names) {
        $entry = $byName[$name]
        if (-not $sources.ContainsKey($name)) {
            throw "entry '$name' has no row in $tableName, section 'Shipped with the product'"
        }
        [void]$out.Append("`n$rule`n")
        [void]$out.Append("$name $($entry.version)`n")
        [void]$out.Append("License: $($entry.license)`n")
        [void]$out.Append("Source: $($sources[$name])`n")
        $packages = @($entry.packages | Where-Object { $null -ne $_ })
        if ($packages.Count -gt 0) { [void]$out.Append("Packages: $($packages -join ', ')`n") }
        [void]$out.Append("$rule`n`n")
        [void]$out.Append($texts[$name])
        [void]$out.Append("`n")
    }
    $bytes = $utf8.GetBytes($out.ToString())
}
catch {
    [Console]::Error.WriteLine('gen-notices: ' + $_.Exception.Message)
    exit 2
}

if ($Check) {
    $current = $null
    if (Test-Path -LiteralPath $Output -PathType Leaf) { $current = [System.IO.File]::ReadAllBytes($Output) }
    if ($null -eq $current -or -not [System.Linq.Enumerable]::SequenceEqual([byte[]]$current, [byte[]]$bytes)) {
        Write-Output 'THIRD-PARTY-NOTICES.txt is out of date'
        exit 1
    }
    exit 0
}

[System.IO.File]::WriteAllBytes($Output, $bytes)
exit 0
